import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd();

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run(['cargo', 'run', '-q', '-p', 'fz', '--', 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload['items']]

plain_owned_return = verify('plain_owned_return', '''
    fn produce() -> *mut u8 {
        let p = alloc(32)
        return p
    }
    fn main() -> i32 {
        let p = produce()
        free(p)
        return 0
    }
''', 0)
assert plain_owned_return['errors'] == 0, plain_owned_return
assert not any('potential resource escape' in message for message in messages(plain_owned_return)), plain_owned_return
assert not any('linear value `p` was not consumed/freed' in message for message in messages(plain_owned_return)), plain_owned_return

grouped_owned_return = verify('grouped_owned_return', '''
    fn produce() -> *mut u8 {
        let p = alloc(32)
        return (p)
    }
    fn main() -> i32 {
        let p = produce()
        free(p)
        return 0
    }
''', 0)
assert grouped_owned_return['errors'] == 0, grouped_owned_return

owned_param_transfer = verify('owned_param_transfer', '''
    fn consume(p: *mut u8) -> i32 {
        free(p)
        return 0
    }
    fn main() -> i32 {
        let p = alloc(32)
        discard consume(p)
        return 0
    }
''', 0)
assert owned_param_transfer['errors'] == 0, owned_param_transfer

double_free = verify('double_free', '''
    fn main() -> i32 {
        let p = alloc(32)
        free(p)
        free(p)
        return 0
    }
''', 1)
assert any('double-frees provenance root 1 via `p`' in message for message in messages(double_free)), double_free
assert any('consumes non-owned or already-consumed value `p` via `free`' in message for message in messages(double_free)), double_free

print('compiler-memory-transfer-ok')

